const IDX: Record<Lang, 0 | 1 | 2> = { pt: 0, en: 1, es: 2 };

// Every variant of every exact message points to its trio, so a message is found whichever language it was stored in.
const exatas = new Map<string, Trio>(EXATAS.flatMap((trio) => trio.map((variante) => [variante, trio] as [string, Trio])));

// Messages that carry a variable part: one template per language ([pt, en, es]); `{0}` is the variable part.
// `nested` marks a part that is itself a message and is translated recursively.
interface Padrao {
  templates: Trio;
  regexes: RegExp[];
  nested?: boolean;
}

function padrao(templates: Trio, parte = "([\\s\\S]*?)", nested = false): Padrao {
  const regexes = templates.map((tpl) => {
    const [antes, depois] = tpl.split("{0}").map((x) => x.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
    return new RegExp(`^${antes}${parte}${depois}$`);
  });
  return { templates, regexes, nested };
}

const PADROES: Padrao[] = [
  padrao(["Arquivo vazio: {0}", "Empty file: {0}", "Archivo vacío: {0}"]),
  padrao(["Extensão não suportada: {0}", "Unsupported extension: {0}", "Extensión no admitida: {0}"]),
  padrao(["Não foi possível conectar no servidor remoto: {0}", "Could not connect to the remote server: {0}", "No se pudo conectar con el servidor remoto: {0}"]),
  padrao(["Não foi possível ler a planilha XLSX: {0}", "Could not read the XLSX spreadsheet: {0}", "No se pudo leer la hoja de cálculo XLSX: {0}"]),
  padrao(["Não foi possível ler o arquivo Word: {0}", "Could not read the Word file: {0}", "No se pudo leer el archivo de Word: {0}"]),
  padrao(["Não foi possível ler {0} como texto; envie um PDF, um Word (.docx), uma planilha XLSX/CSV, ou um arquivo de texto em UTF-8", "Could not read {0} as text; send a PDF, a Word file (.docx), an XLSX/CSV spreadsheet, or a UTF-8 text file", "No se pudo leer {0} como texto; envíe un PDF, un Word (.docx), una hoja XLSX/CSV o un archivo de texto en UTF-8"]),
  padrao(["Não foi possível ler {0} como texto; envie um PDF, uma planilha XLSX/CSV, ou um arquivo de texto/JSON em UTF-8", "Could not read {0} as text; send a PDF, an XLSX/CSV spreadsheet, or a UTF-8 text/JSON file", "No se pudo leer {0} como texto; envíe un PDF, una hoja XLSX/CSV o un archivo de texto/JSON en UTF-8"]),
  padrao(
    [
      "O Gemini não respondeu em {0}s (travou ou está muito lento agora). Tente de novo ou com um documento menor.",
      "Gemini did not answer within {0}s (it hung or is very slow right now). Try again or with a smaller document.",
      "Gemini no respondió en {0}s (se colgó o está muy lento ahora). Inténtelo de nuevo o con un documento más pequeño.",
    ],
    "(\\d+)",
  ),
  padrao(
    ["Erro inesperado ao chamar o Gemini: {0}", "Unexpected error calling Gemini: {0}", "Error inesperado al llamar a Gemini: {0}"],
    "([\\s\\S]*)",
  ),
  // RFI item error: the wrapper is translated and the technical error inside it (itself a known message, or raw Gemini text) too.
  padrao(
    [
      'Não foi possível avaliar este item: {0} Use "Reavaliar" depois de resolver o problema.',
      'Could not evaluate this item: {0} Use "Re-evaluate" after fixing the problem.',
      'No fue posible evaluar este ítem: {0} Use "Reevaluar" después de resolver el problema.',
    ],
    "([\\s\\S]*?)",
    true,
  ),
];

function traduzirUma(texto: string, lang: Lang): string | null {
  const exata = exatas.get(texto);
  if (exata) return exata[IDX[lang]];
  for (const p of PADROES) {
    for (const re of p.regexes) {
      const m = re.exec(texto);
      if (!m) continue;
      const parte = p.nested ? traduzirMensagemServidor(m[1], lang) : m[1];
      return p.templates[IDX[lang]].replace("{0}", () => parte);
    }
  }
  return null;
}

export function traduzirMensagemServidor(texto: string | null | undefined, lang: Lang): string {
  if (!texto) return "";

  // The RFI item error and the extraction errors may be a single line or one line per document ("<file name>: <message>").
  const direta = traduzirUma(texto, lang);
  if (direta) return direta;
  return texto
    .split("\n")
    .map((linha) => {
      const dLinha = traduzirUma(linha, lang);
      if (dLinha) return dLinha;
      const i = linha.indexOf(": ");
      if (i > 0) {
        const resto = traduzirUma(linha.slice(i + 2), lang);
        if (resto) return `${linha.slice(0, i)}: ${resto}`;
      }
      return linha;
    })
    .join("\n");
}
